import{_ as t,o,c as r,a4 as a}from"./chunks/framework.BoUsC9QI.js";const u=JSON.parse('{"title":"Browser support","description":"Material Plus runs in Chrome and Edge 111, Firefox 113 and Safari 16.4 and every later version, on desktop and mobile. The engines behind those versions were…","frontmatter":{"title":"Browser support","order":2},"headers":[],"relativePath":"browser-support.md","filePath":"en/browser-support.md","lastUpdated":1789263063000}'),s={name:"browser-support.md"};function n(i,e,d,h,l,c){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="browser-support" tabindex="-1">Browser support <a class="header-anchor" href="#browser-support" aria-label="Permalink to &quot;Browser support&quot;">​</a></h1><p class="mp-lede">Material Plus runs in <strong>Chrome and Edge 111, Firefox 113 and Safari 16.4</strong> and every later version, on desktop and mobile. The engines behind those versions were run against every demo on this site. In the older ones a few effects are reduced, and the table further down lists each of them.</p><h2 id="the-floor" tabindex="-1">The floor <a class="header-anchor" href="#the-floor" aria-label="Permalink to &quot;The floor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Browser</th><th>Minimum</th><th>Released</th></tr></thead><tbody><tr><td>Chrome, Chrome for Android</td><td>111</td><td>March 2023</td></tr><tr><td>Edge</td><td>111</td><td>March 2023</td></tr><tr><td>Firefox, Firefox for Android</td><td>113</td><td>May 2023</td></tr><tr><td>Safari, Safari on iOS</td><td>16.4</td><td>March 2023</td></tr><tr><td>Samsung Internet</td><td>22</td><td>July 2023</td></tr></tbody></table><p>Both installation paths have the same floor: <code>material-plus-ui/styles.css</code> and <code>material-plus-ui/tailwind.css</code> ship the same token sheet.</p><h2 id="what-sets-it" tabindex="-1">What sets it <a class="header-anchor" href="#what-sets-it" aria-label="Permalink to &quot;What sets it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Chrome, Edge</th><th>Firefox</th><th>Safari</th><th>What depends on it</th></tr></thead><tbody><tr><td>Base UI 1</td><td>111</td><td>113</td><td>16.4</td><td>Focus, keyboard and popup behaviour, from Base UI&#39;s own browser list</td></tr><tr><td><code>oklch()</code> colours</td><td>111</td><td>113</td><td>15.4</td><td>Every colour token, including the fallback roles described below</td></tr><tr><td><code>@layer</code></td><td>99</td><td>97</td><td>15.4</td><td>The cascade layer the tokens sit in</td></tr><tr><td>The package&#39;s JavaScript</td><td>85</td><td>79</td><td>14.1</td><td>Syntax up to ES2021, shipped untranspiled</td></tr></tbody></table><p>The floor is the highest number in each column. React 18 and 19 need nothing newer than the last row.</p><p>Tailwind CSS v4 names Firefox 128 as its own floor, because it relies on registered custom properties. It ships fallbacks for the utilities that use them, and the demos render in Firefox 113 with only the differences listed in the next section.</p><p>Below the floor the library is not supported. In a browser older than Chrome 111, Firefox 113 or Safari 15.4 the colour tokens are not drawn at all, because they are <code>oklch()</code> colours.</p><h2 id="what-is-reduced-in-older-versions" tabindex="-1">What is reduced in older versions <a class="header-anchor" href="#what-is-reduced-in-older-versions" aria-label="Permalink to &quot;What is reduced in older versions&quot;">​</a></h2><p>Everything on this list keeps working. It looks or moves differently, and only in the versions named.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Reduced in</th><th>What happens there</th></tr></thead><tbody><tr><td>Theming from <code>--mp-source-color</code></td><td>Chrome and Edge before 119, Firefox before 128, Safari before 18</td><td>The default scheme is drawn, light or dark. A role set through <code>--mp-sys-color-*</code> still applies</td></tr><tr><td>Counting in <a href="./components/motion/animate-counter"><code>MPAnimateCounter</code></a></td><td>Firefox before 128</td><td>The number jumps to its value instead of counting up to it</td></tr><tr><td>The travelling light in <a href="./components/motion/animate-lighting"><code>MPAnimateLighting</code></a></td><td>Firefox before 128, Safari 16.4</td><td>The glow is drawn but does not travel</td></tr><tr><td>The focus ring in <a href="./components/inputs/rating"><code>MPRating</code></a></td><td>Firefox before 121</td><td>A star clicked with a pointer is ringed too, not only one reached from the keyboard</td></tr><tr><td>Splitting text into letters and words for the text effects</td><td>Firefox before 125</td><td>Text splits on code points and on spaces, so a combined emoji comes apart and a sentence with no spaces counts as one word</td></tr><tr><td>The quieter description in <a href="./components/display/pill"><code>MPPill</code></a></td><td>Safari before 17</td><td>The description is drawn in the title&#39;s colour</td></tr><tr><td>Scroll-driven animations, <code>timeline=&quot;view&quot;</code> on the <a href="./components/motion/animate-fade#scrolling-is-a-clock">Animate components</a></td><td>Chrome and Edge before 115, Firefox, Safari before 26</td><td>The effect plays once on the clock</td></tr><tr><td>Week information in <code>Intl.Locale</code></td><td>Firefox before 153</td><td>The calendars start the week on Sunday unless <code>weekStartsOn</code> is set</td></tr></tbody></table><h2 id="how-the-colour-roles-reach-older-browsers" tabindex="-1">How the colour roles reach older browsers <a class="header-anchor" href="#how-the-colour-roles-reach-older-browsers" aria-label="Permalink to &quot;How the colour roles reach older browsers&quot;">​</a></h2><p>A role such as <code>primary</code> is not a fixed colour. It is computed in the browser, on each element, from whatever <code>--mp-source-color</code> is in scope there:</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">oklch(from var(--mp-source-color) var(--tone) var(--chroma) h)</span></span></code></pre></div><p>That is what lets one <code>--mp-source-color</code> on a section retheme that section, or change at runtime from an inline style. <a href="./design/color#how-a-role-is-derived">Colour</a> explains the derivation, and <a href="./design/color#inside-srgb">Inside sRGB</a> how the accent and error roles are kept inside the gamut. That second step puts <code>clamp()</code> and <code>min()</code> on the channels of a relative colour, and those are the newest things the stylesheet depends on. So it writes the whole default scheme out a second time, as plain colours, for the browsers without them: Chrome and Edge before 119, Firefox before 128 and Safari before 18. Safari 16.4 to 17.6 have relative colour syntax from an earlier draft of the specification, which accepts neither.</p><p>In those browsers the colours are the default scheme&#39;s, light or dark, and a <code>--mp-source-color</code> of your own changes nothing, because reading a hue out of a colour is what they cannot do. A browser with the current syntax skips that copy. Chrome and Edge 119 to 121 have it according to MDN&#39;s data, but they do not start on the macOS the measurements were taken on, so they were not run.</p><h3 id="theming-in-the-older-browsers" tabindex="-1">Theming in the older browsers <a class="header-anchor" href="#theming-in-the-older-browsers" aria-label="Permalink to &quot;Theming in the older browsers&quot;">​</a></h3><p>A role you set yourself wins in every browser, because each role reads <code>--mp-sys-color-*</code> first and Material Web&#39;s <code>--md-sys-color-*</code> second, before any derivation or fallback:</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  --mp-sys-color-primary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">#00639b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  --mp-sys-color-on-primary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">#ffffff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  /* …and the other roles you want to change */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A brand that has to appear in Chrome 111 to 118, Firefox 113 to 127 or Safari 16.4 to 17.6 therefore sets its roles this way, once for each scheme it uses. <a href="./design/color#a-single-role">A single role</a> lists the variables.</p><h2 id="how-these-numbers-were-found" tabindex="-1">How these numbers were found <a class="header-anchor" href="#how-these-numbers-were-found" aria-label="Permalink to &quot;How these numbers were found&quot;">​</a></h2><p>Every demo on this site was rendered in one page, each behind its own error boundary, and the page was opened in Playwright&#39;s builds of Chromium 111, Firefox 113, 127 and 128, and WebKit 16.4, 17.4 and 18.0, and in Chrome for Testing 122. In each one the run checked for render and page errors and compared all 29 colour roles in both schemes with a current Chromium. In the three oldest it also opened nine popups, from a select to a command palette, and the counter, the lighting effect and the rating&#39;s focus ring were checked in the versions the table names. The WebKit builds are Playwright&#39;s builds of the engine at the Safari version they are named for, not Safari itself.</p><p>Versions between those were not run. For them, and for the version each requirement and feature above was introduced in, the numbers come from <a href="https://github.com/mdn/browser-compat-data" target="_blank" rel="noreferrer">MDN&#39;s browser compatibility data</a> and from what Base UI and Tailwind CSS publish for themselves. The test suite itself runs in the current releases of Chromium, Firefox and WebKit on Linux, Windows and macOS.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./design/color">Colour</a> — how the roles are derived, and how to set one yourself.</li><li><a href="./guide/getting-started">Getting started</a> — installation and setup.</li><li><a href="./changelog">Changelog</a> — what changed in each release.</li></ul>`,27)])])}const f=t(s,[["render",n]]);export{u as __pageData,f as default};
